[{"type":"text","text":"// H5 发起检查「本地草稿」缓存。
// 后端改造后 /check/start 不再落库，仅返回填写页数据；在用户最终提交前，
// 所有填写内容都只保存在本地（本工具）。本地草稿不属于后端单据，不会出现在任何列表/统计里。
import type { CheckForm } from '../types/evaluation'

const DRAFT_KEY = 'pc-check-draft:active'

/** 把 /start 返回值或用户实时填写的表单持久化到本地（不做深拷贝，调用方传入的即快照） */
export function saveCheckDraft(form: CheckForm): void {
  try {
    uni.setStorageSync(DRAFT_KEY, JSON.stringify(form))
  } catch { /* 本地存储不可用（隐私模式/超限）时静默降级，不阻断填写 */ }
}

/** 读取当前本地草稿；无草稿或数据损坏时返回 null */
export function loadCheckDraft(): CheckForm | null {
  try {
    const raw = uni.getStorageSync(DRAFT_KEY)
    if (!raw) return null
    const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw
    if (!parsed || typeof parsed !== 'object' || !Array.isArray(parsed.categoryList)) return null
    return parsed as CheckForm
  } catch {
    return null
  }
}

/** 提交成功后清理本地草稿，避免与下一次发起的单据串数据 */
export function clearCheckDraft(): void {
  try {
    uni.removeStorageSync(DRAFT_KEY)
  } catch { /* ignore */ }
}
"}]

